'use server';
import { createSupabaseServerClient } from '@/lib/supabase/server';
import { fetchMemberStatus } from '@/lib/member-status-api';
import { NextResponse } from 'next/server';
import { cookies } from 'next/headers';

export async function GET(request: Request) {
  const origin = process.env.NEXT_PUBLIC_APP_URL!;
  const { searchParams } = new URL(request.url)
  const code = searchParams.get('code')
  const errorParam = searchParams.get('error');
  const errorDescription = searchParams.get('error_description');

  // Cookieから登録ページのパスを取得（もしあれば）
  const cookieStore = await cookies();
  const authNext = cookieStore.get('auth_next')?.value;
  const next = authNext || searchParams.get('next') || '/dashboard';

  // 使用済みCookieを削除
  if (authNext) {
    cookieStore.delete('auth_next');
  }

  console.log('[AUTH CALLBACK] ========================================');
  console.log('[AUTH CALLBACK] Timestamp:', new Date().toISOString());
  console.log('[AUTH CALLBACK] Request URL:', request.url);
  console.log('[AUTH CALLBACK] Origin:', origin);
  console.log('[AUTH CALLBACK] Next redirect:', next);
  console.log('[AUTH CALLBACK] Code present:', !!code);
  console.log('[AUTH CALLBACK] Error param:', errorParam);
  console.log('[AUTH CALLBACK] Error description:', errorDescription);
  if (code) {
    console.log('[AUTH CALLBACK] Code (first 20 chars):', code.substring(0, 20) + '...');
  }

  // OAuthプロバイダーからのエラーをチェック
  if (errorParam) {
    console.error('[AUTH CALLBACK] ❌ OAuth error from provider');
    console.error('[AUTH CALLBACK] Error:', errorParam);
    console.error('[AUTH CALLBACK] Error code:', searchParams.get('error_code'));
    console.error('[AUTH CALLBACK] Error description:', errorDescription);
    console.error('[AUTH CALLBACK] ========================================');

    // ユーザーに分かりやすいエラーメッセージを表示
    let userMessage = '認証中にエラーが発生しました。';
    if (errorDescription?.includes('Unable to exchange external code')) {
      userMessage = '認証の処理中にエラーが発生しました。時間をおいて再度お試しください。改善しない場合は管理者にお問い合わせください。';
    } else if (errorDescription) {
      userMessage = errorDescription;
    }

    return NextResponse.redirect(`${origin}/login?error=${encodeURIComponent(userMessage)}`);
  }

  if (!code) {
    console.error('[AUTH CALLBACK] No code parameter in callback URL');
    return NextResponse.redirect(`${origin}/login?error=認証コードが見つかりません。`);
  }

  const supabase = await createSupabaseServerClient();

  console.log('[AUTH CALLBACK] Attempting code exchange with Supabase...');
  // PKCEフローでコードをセッションに交換
  const { data, error } = await supabase.auth.exchangeCodeForSession(code);

  if (error) {
    console.error('[AUTH CALLBACK] ❌ Code exchange FAILED');
    console.error('[AUTH CALLBACK] Error name:', error.name);
    console.error('[AUTH CALLBACK] Error message:', error.message);
    console.error('[AUTH CALLBACK] Error status:', error.status);
    console.error('[AUTH CALLBACK] Error code:', error.code);
    console.error('[AUTH CALLBACK] Full error object:', JSON.stringify(error, null, 2));

    // PKCEエラーの場合は再ログインを促す
    if (error.message.includes('flow state')) {
      return NextResponse.redirect(`${origin}/login?error=セッションの有効期限が切れました。もう一度ログインしてください。`);
    }
    return NextResponse.redirect(`${origin}/login?error=セッションの確立に失敗しました: ${error.message}`);
  }

  console.log('[AUTH CALLBACK] ✅ Code exchange successful');

  if (!data.session || !data.user) {
    console.error('[AUTH CALLBACK] ❌ No session or user in response');
    console.error('[AUTH CALLBACK] data.session:', !!data.session);
    console.error('[AUTH CALLBACK] data.user:', !!data.user);
    return NextResponse.redirect(`${origin}/login?error=セッションの確立に失敗しました。`);
  }

  console.log('[AUTH CALLBACK] User ID:', data.user.id);
  console.log('[AUTH CALLBACK] User email:', data.user.email);
  console.log('[AUTH CALLBACK] Session expires at:', data.session.expires_at);
  console.log('[AUTH CALLBACK] User metadata:', JSON.stringify(data.user.user_metadata, null, 2));

  const discordUid = data.user.user_metadata.provider_id;
  console.log('[AUTH CALLBACK] Discord UID:', discordUid);

  if (!discordUid) {
      console.error('[AUTH CALLBACK] ❌ Discord UID not found in user metadata');
      await supabase.auth.signOut();
      return NextResponse.redirect(`${origin}/login?error=DiscordユーザーIDが取得できませんでした。`);
  }

  // Discord サーバー所属チェック（一時的にコメントアウト）
  /*
  const { data: memberStatus, error: apiError } = await fetchMemberStatus(discordUid);

  if (apiError) {
      console.error('Error fetching member status from API:', apiError);
      await supabase.auth.signOut();
      return NextResponse.redirect(`${origin}/login?error=APIとの通信中にエラーが発生しました。しばらく待ってから再度お試しください。`);
  }

  if (!memberStatus || !memberStatus.is_in_server) {
      await supabase.auth.signOut();
      return NextResponse.redirect(`${origin}/login?error=指定されたDiscordサーバーのメンバーではありません。`);
  }
  */

  // member.members テーブルにユーザーが登録されているかチェック
  console.log('[AUTH CALLBACK] Checking member.members table for Discord UID:', discordUid);
  const { data: memberRecord, error: memberError } = await supabase
    .schema('member')
    .from('members')
    .select('supabase_auth_user_id')
    .eq('discord_uid', discordUid)
    .single();

  if (memberError) {
    console.error('[AUTH CALLBACK] ❌ Member lookup error');
    console.error('[AUTH CALLBACK] Error code:', memberError.code);
    console.error('[AUTH CALLBACK] Error message:', memberError.message);
    console.error('[AUTH CALLBACK] Error details:', memberError.details);
    console.error('[AUTH CALLBACK] Error hint:', memberError.hint);
  }

  if (memberError || !memberRecord) {
      console.log('[AUTH CALLBACK] ❌ User not found in member.members table');
      console.log('[AUTH CALLBACK] Discord UID searched:', discordUid);
      console.log('[AUTH CALLBACK] Member record:', memberRecord);
      await supabase.auth.signOut();
      return NextResponse.redirect(`${origin}/login?error=not_registered`);
  }

  console.log('[AUTH CALLBACK] ✅ User found in members table');
  console.log('[AUTH CALLBACK] Member supabase_auth_user_id:', memberRecord.supabase_auth_user_id);
  console.log('[AUTH CALLBACK] Redirecting to:', next);
  console.log('[AUTH CALLBACK] ========================================');

  return NextResponse.redirect(`${origin}${next}`);
}

import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { createSupabaseServerClient } from "@/lib/supabase/server";
import { BarChart, Calendar as CalendarIcon, Clock, Percent } from "lucide-react";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table"
import { Badge } from "@/components/ui/badge";
import { subDays } from "date-fns";
import AttendanceCalendar from "./components/AttendanceCalendar";
import ClientRelativeTime from "./components/ClientRelativeTime";
import CardMigrationAlert from "./components/CardMigrationAlert";
import { calculateTotalActivityTime } from "../actions";
import { convertGenerationToGrade, formatJst } from "@/lib/utils";
import { redirect } from "next/navigation";
import { toZonedTime } from "date-fns-tz";

export const dynamic = 'force-dynamic';

const timeZone = 'Asia/Tokyo';

export default async function DashboardPage() {
    const supabase = await createSupabaseServerClient();
    const { data: { user } } = await supabase.auth.getUser();

    if (!user) {
        redirect('/login');
    }

    // プロフィールと勤怠ユーザーを並列取得
    const [profileResult, attendanceUserResult] = await Promise.all([
      supabase
        .schema('member')
        .from('members')
        .select(`
            discord_uid,
            generation,
            is_admin,
            joined_at,
            display_name,
            member_team_relations(teams(name))
        `)
        .eq('supabase_auth_user_id', user!.id)
        .single(),
      supabase
        .schema('attendance')
        .from('users')
        .select('card_id')
        .eq('supabase_auth_user_id', user!.id)
        .single(),
    ]);

    const { data: profile, error: profileError } = profileResult;

    if (profileError || !profile) {
        console.error('Profile fetch error:', profileError);
        redirect('/register/member-unregistered');
    }

    const hasCardId = attendanceUserResult.data?.card_id && attendanceUserResult.data.card_id.trim() !== '';

    // display_nameがDBにあればそれを使用（Discord API不要）
    const displayName = profile.display_name || '名無しさん';
    let firstname = '';
    let lastname = '';
    if (displayName !== '名無しさん') {
        const nameParts = displayName.split(/\s+/);
        if (nameParts.length >= 2) {
            lastname = nameParts[0].toLowerCase();
            firstname = nameParts[1].toLowerCase();
        }
    }

    const today = toZonedTime(new Date(), timeZone);
    const thirtyDaysAgo = formatJst(subDays(today, 30), 'yyyy-MM-dd');
    const userCreatedAtDate = formatJst(new Date(profile!.joined_at), 'yyyy-MM-dd');

    // 出勤データの取得を全て並列化
    const [attendancesResult, totalActivityTimeInHours, distinctDatesResult, totalClubActivityDatesResult] = await Promise.all([
      supabase.schema('attendance').from('attendances').select('*').eq('user_id', user!.id).order('timestamp', { ascending: false }).limit(5),
      calculateTotalActivityTime(user!.id, 30),
      supabase
        .schema('attendance')
        .from('attendances')
        .select('date')
        .eq('user_id', user!.id)
        .eq('type', 'in')
        .gte('date', thirtyDaysAgo),
      supabase
        .schema('attendance')
        .from('attendances')
        .select('date')
        .eq('type', 'in')
        .gte('date', thirtyDaysAgo)
        .gte('date', userCreatedAtDate),
    ]);

    const { data: attendances } = attendancesResult;
    const { data: distinctDates } = distinctDatesResult;
    const { data: totalClubActivityDates } = totalClubActivityDatesResult;

    const userAttendanceDays = distinctDates ? new Set(distinctDates.map(d => d.date)).size : 0;
    const totalClubDays = totalClubActivityDates ? new Set(totalClubActivityDates.map(d => d.date)).size : 0;

    const attendanceRate = totalClubDays > 0 ? (userAttendanceDays / totalClubDays) * 100 : 0;

    const teamName = profile?.member_team_relations?.[0]?.teams?.name;

  return (
    <div className="space-y-6">
        {!hasCardId && (
            <CardMigrationAlert
                userId={user!.id}
                firstname={firstname}
                lastname={lastname}
            />
        )}

        <div className="flex justify-between items-start">
            <div>
                <h1 className="text-3xl font-bold">マイダッシュボード</h1>
                <p className="text-muted-foreground">こんにちは, {displayName}さん！</p>
            </div>
            <div className="text-right">
                {teamName && <Badge variant="secondary">{teamName}</Badge>}
                <p className="text-sm text-muted-foreground">{profile?.generation ? convertGenerationToGrade(profile.generation) : ''}</p>
            </div>
        </div>

        <div className="grid gap-4 grid-cols-1 sm:grid-cols-2 lg:grid-cols-4">
            <Card>
                <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
                    <CardTitle className="text-sm font-medium">出勤日数</CardTitle>
                    <CalendarIcon className="h-4 w-4 text-muted-foreground" />
                </CardHeader>
                <CardContent>
                    <div className="text-2xl font-bold">{userAttendanceDays}日</div>
                     <p className="text-xs text-muted-foreground">
                        過去30日間
                    </p>
                </CardContent>
            </Card>
            <Card>
                <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
                    <CardTitle className="text-sm font-medium">活動時間 (概算)</CardTitle>
                    <Clock className="h-4 w-4 text-muted-foreground" />
                </CardHeader>
                <CardContent>
                    <div className="text-2xl font-bold">{totalActivityTimeInHours.toFixed(1)} 時間</div>
                    <p className="text-xs text-muted-foreground">
                        過去30日間
                    </p>
                </CardContent>
            </Card>
            <Card>
                <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
                    <CardTitle className="text-sm font-medium">出勤率</CardTitle>
                    <Percent className="h-4 w-4 text-muted-foreground" />
                </CardHeader>
                <CardContent>
                    <div className="text-2xl font-bold">{attendanceRate.toFixed(1)}%</div>
                    <p className="text-xs text-muted-foreground">
                        活動日数(登録後): {totalClubDays}日
                    </p>
                </CardContent>
            </Card>
            <Card>
                <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
                    <CardTitle className="text-sm font-medium">直近の活動</CardTitle>
                    <BarChart className="h-4 w-4 text-muted-foreground" />
                </CardHeader>
                <CardContent>
                    <div className="text-2xl font-bold">{attendances && attendances.length > 0 ? (attendances[0].type === 'in' ? '活動中' : '退勤済み') : '記録なし'}</div>
                </CardContent>
            </Card>
      </div>
      <div className="grid gap-6">
        <div className="grid gap-6">
            <Card>
                <CardHeader>
                    <CardTitle>最近の出退勤記録</CardTitle>
                </CardHeader>
                <CardContent>
                    <Table>
                        <TableHeader>
                            <TableRow>
                            <TableHead>種別</TableHead>
                            <TableHead>日時</TableHead>
                            <TableHead>相対時間</TableHead>
                            </TableRow>
                        </TableHeader>
                        <TableBody>
                            {attendances && attendances.length > 0 ? attendances.map((att) => (
                                <TableRow key={att.id}>
                                    <TableCell>
                                        <Badge variant={att.type === 'in' ? 'default' : 'secondary'}>
                                            {att.type === 'in' ? '出勤' : '退勤'}
                                        </Badge>
                                    </TableCell>
                                    <TableCell>{formatJst(new Date(att.timestamp), 'yyyy/MM/dd HH:mm:ss')}</TableCell>
                                    <TableCell><ClientRelativeTime date={att.timestamp} /></TableCell>
                                </TableRow>
                            )) : (
                                <TableRow>
                                    <TableCell colSpan={3} className="text-center">記録がありません。</TableCell>
                                </TableRow>
                            )}
                        </TableBody>
                    </Table>
                </CardContent>
            </Card>
             <Card>
                <CardHeader>
